def total_to(n):
    if n == 0:
        return 0
    return n + total_to(n - 1)
print(total_to(3))

class Device:
    def __init__(self, name, battery):
        self.name = name
        self.battery = battery
    def run(self, cost):
        if cost < 0 or cost > self.battery:
            return False
        self.battery -= cost
        return True
first = Device("A", 10)
second = Device("B", 10)
print(first.run(6), first.run(5))
print(first.battery, second.battery)

