def binary_search(a, target):
    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        print(left, mid, right, a[mid])
        if a[mid] == target:
            return mid
        if a[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

print("index", binary_search([2, 4, 6, 8, 10], 7))

def quick_sort(a):
    if len(a) <= 1: return a.copy()
    pivot = a[len(a)//2]
    return quick_sort([x for x in a if x < pivot]) + [x for x in a if x == pivot] + quick_sort([x for x in a if x > pivot])
print(quick_sort([4, 1, 3, 2]))

from collections import deque
graph = {"S": ["A", "B"], "A": ["S", "C", "D"],
         "B": ["S", "D"], "C": ["A", "T"],
         "D": ["A", "B", "T"], "T": ["C", "D"]}
queue = deque(["S"])
distance, parent = {"S": 0}, {"S": None}
while queue:
    node = queue.popleft()
    print(node, distance[node])
    for neighbor in graph[node]:
        if neighbor not in distance:
            distance[neighbor] = distance[node] + 1
            parent[neighbor] = node
            queue.append(neighbor)
path, node = [], "T"
while node is not None:
    path.append(node)
    node = parent[node]
print("path", " -> ".join(reversed(path)))

